  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  fontWeight: {
    type: "number",
    default: 400,
    min: 400,
    max: 500,
    step: 100,
    description: "Weight",
    hiddenFromList: false,
  },
  dim: {
    type: "number",
    default: 0.62,
    min: 0.2,
    max: 1,
    step: 0.02,
    description: "Snag dim",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Afacad",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
